contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash, uint amount) public payable {
        require(amount == 1 ether, "amount must equal 1 ether");
        require(address(this).balance >= amount, "not enough balance");

        uint balBefore = address(this).balance;

        bool reverted;
        try c.lockInGuess{value: amount}(hash) {
            reverted = false;
        } catch {
            reverted = true;
